          else if (prompts[MY_KEY] === entry) delete prompts[MY_KEY];
        };
        if (!quiet) notify('已挂到酒馆系统提示层 · ' + JB.length + ' 字');
      } else {
        var injected = injectPrompts([{ id: MY_KEY, position: 'in_chat', depth: 0, role: 'system', content: JB, should_scan: true }]);
        releasePrompt = function () {
          if (typeof injected?.uninject === 'function') injected.uninject();
          else if (typeof uninjectPrompts === 'function') uninjectPrompts([MY_KEY]);
        };
        if (!quiet) console.warn('[新中市] 酒馆系统提示接口不可用，已使用兼容注入。');
      }
      scope = ctx;
      try { localStorage.setItem(KEY, MINE); } catch (e) {}
    } catch (e) { notify('提示注入失败：' + e.message, 'error'); }
  }

  function clearPrompt() {
    try { if (releasePrompt) releasePrompt(); } catch (e) {}
    releasePrompt = null;
  }

  function detach() {
    clearPrompt();
    try { if (localStorage.getItem(KEY) === MINE) localStorage.removeItem(KEY); } catch (e) {}
    notify('已移除提示');
  }

  function restore() {
    if (!releasePrompt) return;
    var ctx = api();
    if (scope && (!ctx || scope.characterId !== ctx.characterId || scope.groupId !== ctx.groupId)) return;
    try { if (localStorage.getItem(KEY) !== MINE) return; } catch (e) {}
    apply(true);
  }

  apply();
  try {
    if (typeof eventOn === 'function') eventOn(tavern_events.CHAT_CHANGED, restore);
    else if (typeof onEvent === 'function') onEvent('CHAT_CHANGED', restore);
  } catch (e) {}
  window.addEventListener('pagehide', clearPrompt);
  try { window.xzsJb = { on: apply, off: detach, mode: MINE, key: MY_KEY, text: JB }; } catch (e) {}
})();

// 破限4·硬派论证 · 系统提示层版
