        let url;
        try { url = new URL(typeof input === 'string' ? input : input?.url || input?.href, host.location.href); } catch { return forward(); }
        if (url.origin !== host.location.origin || !/^\/api\/backends\/[^/]+\/generate\/?$/.test(url.pathname)) return forward();
