            nativeTurn.record = record;
            nativeTurn.index = scoped.chat.length - (['continue','swipe'].includes(nativeTurn.type) ? 1 : 0);
        }
        async function send(next, requestSignal = signal, kind = 'initial') {
            const current = tavernContext();
