            if (record.end || disposed) return;
            current.observe?.visible(current.chars);
            Object.assign(record, { chars: current.chars, chunks: current.chunks, responseModel: current.responseModel, detail: current.sawTarget ? '正在解包工具参数' : '正在接收文本' }); schedule();
