            if (!(Number(payload.n) > 1) && response.body && (/event-stream|json/.test(type) || payload.stream === true)) {
                return await Recovery.relay(response, {
                    signal, payload, abort, send, fail, progress, trace, headers: cleanedHeaders(response.headers),
                    setTimer: (fn, ms) => host.setTimeout(fn, ms), clearTimer: id => host.clearTimeout(id),
                    finish(status, detail, chars, delivery) {
