                });
            }
            if ((type.includes('text/event-stream') || payload.stream === true && !type.includes('json')) && response.body) {
                rw.observe = trace;
                const stream = Core.wrapStream(response.body, rw, (status, detail) => end(status, detail, rw), signal);
                const headers = cleanedHeaders(response.headers);
                headers.set('content-type', 'text/event-stream; charset=utf-8');
